package com.metaobjects.generator.kotlin

import com.metaobjects.metadata.ktx.loadString
import java.nio.file.Files
import kotlin.test.Test
import kotlin.test.assertTrue

/**
 * The generated by-id surface must derive its key type from the entity's
 * `identity.primary` field — NOT hard-code `Long`. For a `field.uuid` PK
 * (`@generation: uuid`) the data class + Exposed column are already
 * `java.util.UUID` / `Column<UUID>`, so a hard-coded `Long`:
 *
 *  - controller: `@PathVariable id: Long` then `pkField eq id` against a
 *    `Column<UUID>` — a TYPE ERROR (the generated file does not compile);
 *  - Exposed table: a FK `long("col").references(Column<UUID>)` — also a
 *    compile error, so ANY relationship pointing at a uuid-PK entity broke
 *    the build;
 *  - relations: the helper param was already derived (UUID) but the file
 *    never imported `java.util.UUID` — unresolved reference.
 *
 * Mirrors the C# `RoutesGenerator`, which derives the PK scalar via
 * `CSharpNaming.ScalarFor` and threads it through get/update/delete/M:N/TPH.
 * The end-to-end compile proof lives in `integration-tests-kotlin`
 * (`UuidPkControllerRunTest`); these are the fast string gates.
 */
class KotlinUuidPrimaryKeyCodegenTest {

    /** uuid-PK Note —tags→ uuid-PK Tag via NoteTag (M:N), all keyed by field.uuid. */
    private val uuidM2mFixture = """{
      "metadata.root": { "package": "acme::notes", "children": [
        { "object.entity": { "name": "Note", "children": [
            { "source.rdb":   { "@table": "notes" } },
            { "field.uuid":   { "name": "id" } },
            { "field.string": { "name": "title", "@required": true, "@maxLength": 200 } },
            { "relationship.association": { "name": "tags", "@cardinality": "many",
                "@objectRef": "Tag", "@through": "NoteTag" } },
            { "identity.primary": { "@fields": "id", "@generation": "uuid" } }
        ] } },
        { "object.entity": { "name": "Tag", "children": [
            { "source.rdb":   { "@table": "tags" } },
            { "field.uuid":   { "name": "id" } },
            { "field.string": { "name": "name", "@required": true, "@maxLength": 80 } },
            { "identity.primary": { "@fields": "id", "@generation": "uuid" } }
        ] } },
        { "object.entity": { "name": "NoteTag", "children": [
            { "source.rdb":         { "@table": "note_tags" } },
            { "field.uuid":         { "name": "noteId", "@required": true } },
            { "field.uuid":         { "name": "tagId",  "@required": true } },
            { "identity.primary":   { "@fields": ["noteId", "tagId"] } },
            { "identity.reference": { "name": "fkNote", "@fields": "noteId", "@references": "Note" } },
            { "identity.reference": { "name": "fkTag",  "@fields": "tagId",  "@references": "Tag" } }
        ] } }
      ] }
    }""".trimIndent()

    /** uuid-PK Author with a declared to-one FK from Post AND an inverse to-many to Comment. */
    private val uuidFkFixture = """{
      "metadata.root": { "package": "acme::demo", "children": [
        { "object.entity": { "name": "Author", "children": [
            { "source.rdb":   { "@table": "authors" } },
            { "field.uuid":   { "name": "id" } },
            { "field.string": { "name": "name", "@required": true, "@maxLength": 80 } },
            { "relationship.composition": { "name": "comments", "@objectRef": "Comment", "@cardinality": "many" } },
            { "identity.primary": { "@fields": "id", "@generation": "uuid" } }
        ] } },
        { "object.entity": { "name": "Post", "children": [
            { "source.rdb":   { "@table": "posts" } },
            { "field.long":   { "name": "id" } },
            { "field.string": { "name": "title", "@required": true, "@maxLength": 200 } },
            { "relationship.composition": { "name": "author", "@objectRef": "Author" } },
            { "identity.primary": { "@fields": "id", "@generation": "increment" } }
        ] } },
        { "object.entity": { "name": "Comment", "children": [
            { "source.rdb":   { "@table": "comments" } },
            { "field.long":   { "name": "id" } },
            { "field.string": { "name": "body", "@required": true } },
            { "identity.primary": { "@fields": "id", "@generation": "increment" } }
        ] } }
      ] }
    }""".trimIndent()

    /** FR-017 TPH hierarchy whose single-table base is keyed by a field.uuid PK. */
    private val uuidTphFixture = """{
      "metadata.root": { "package": "acme::auth", "children": [
        { "object.entity": { "name": "Auth", "@discriminator": "type", "children": [
            { "source.rdb":   { "@table": "auths" } },
            { "field.uuid":   { "name": "id" } },
            { "field.enum":   { "name": "type", "@values": ["Bridge", "Copay"] } },
            { "field.string": { "name": "reference", "@required": true, "@maxLength": 80 } },
            { "identity.primary": { "@fields": "id", "@generation": "uuid" } }
        ] } },
        { "object.entity": { "name": "BridgeAuth", "extends": "Auth",
            "@discriminatorValue": "Bridge", "children": [
            { "field.int": { "name": "quantity" } }
        ] } },
        { "object.entity": { "name": "CopayAuth", "extends": "Auth",
            "@discriminatorValue": "Copay", "children": [
            { "field.string": { "name": "copayCode", "@maxLength": 40 } }
        ] } }
      ] }
    }""".trimIndent()

    private fun generate(gen: com.metaobjects.generator.direct.MultiFileDirectGeneratorBase<*>,
                         fixtureName: String, fixture: String, relPath: String): String {
        val outDir = Files.createTempDirectory("kuuid-")
        try {
            gen.setArgs(mapOf("outputDir" to outDir.toString()))
            gen.execute(loadString(fixtureName, fixture))
            val f = outDir.resolve(relPath)
            assertTrue(Files.exists(f),
                "expected generated file $f; files=${Files.walk(outDir).toList()}")
            return Files.readString(f)
        } finally {
            outDir.toFile().deleteRecursively()
        }
    }

    @Test fun `uuid PK controller binds UUID path variables and imports the type`() {
        val src = generate(KotlinSpringControllerGenerator(), "kuuid-ctrl", uuidM2mFixture,
            "acme/notes/NoteController.kt")

        assertTrue("fun get(@PathVariable id: UUID)" in src,
            "expected get(@PathVariable id: UUID); saw:\n$src")
        assertTrue("fun update(@PathVariable id: UUID," in src,
            "expected update(@PathVariable id: UUID, ...); saw:\n$src")
        assertTrue("fun delete(@PathVariable id: UUID)" in src,
            "expected delete(@PathVariable id: UUID); saw:\n$src")
        // FR-018 M:N traversal endpoint binds the SOURCE id as its PK type too.
        assertTrue("fun tags(@PathVariable id: UUID)" in src,
            "expected M:N tags(@PathVariable id: UUID); saw:\n$src")
        // The UUID simple name must be importable.
        assertTrue("import java.util.UUID" in src,
            "expected import java.util.UUID; saw:\n$src")
        assertTrue("@PathVariable id: Long" !in src,
            "uuid-PK controller must not bind @PathVariable id: Long; saw:\n$src")
    }

    @Test fun `declared FK column to a uuid-PK entity is a uuid column`() {
        val src = generate(KotlinExposedTableGenerator(), "kuuid-fk-decl", uuidFkFixture,
            "acme/demo/PostTable.kt")
        // Exposed's typed references() requires the FK column's SQL type to match the
        // referenced PK's — long("author_id").references(Column<UUID>) does not compile.
        assertTrue("val authorId = uuid(\"author_id\").references(AuthorTable.id)" in src,
            "expected uuid(\"author_id\").references(AuthorTable.id); saw:\n$src")
        assertTrue("long(\"author_id\")" !in src,
            "FK to a uuid PK must not be a long column; saw:\n$src")
    }

    @Test fun `inferred inverse FK column from a uuid-PK owner is a uuid column`() {
        val src = generate(KotlinExposedTableGenerator(), "kuuid-fk-inv", uuidFkFixture,
            "acme/demo/CommentTable.kt")
        assertTrue("val authorId = uuid(\"author_id\").references(AuthorTable.id)" in src,
            "expected inferred uuid(\"author_id\") FK on CommentTable; saw:\n$src")
        assertTrue("long(\"author_id\")" !in src,
            "inverse FK to a uuid-PK owner must not be a long column; saw:\n$src")
    }

    @Test fun `relations helpers for a uuid-PK owner import UUID`() {
        val src = generate(KotlinRelationsGenerator(), "kuuid-rel", uuidFkFixture,
            "acme/demo/AuthorRelations.kt")
        // The param type was already derived (UUID) — but without the import the
        // generated file had an unresolved reference.
        assertTrue("fun AuthorTable.commentsQuery(authorId: UUID)" in src,
            "expected commentsQuery(authorId: UUID); saw:\n$src")
        assertTrue("import java.util.UUID" in src,
            "expected import java.util.UUID in AuthorRelations.kt; saw:\n$src")
    }

    @Test fun `uuid PK TPH controller binds UUID at every by-id route`() {
        val src = generate(KotlinSpringControllerGenerator(), "kuuid-tph", uuidTphFixture,
            "acme/auth/AuthController.kt")
        assertTrue("fun get(@PathVariable id: UUID)" in src,
            "expected polymorphic get(@PathVariable id: UUID); saw:\n$src")
        assertTrue("fun getBridge(@PathVariable id: UUID)" in src,
            "expected per-subtype getBridge(@PathVariable id: UUID); saw:\n$src")
        assertTrue("fun updateBridge(@PathVariable id: UUID," in src,
            "expected per-subtype updateBridge(@PathVariable id: UUID, ...); saw:\n$src")
        assertTrue("fun deleteCopay(@PathVariable id: UUID)" in src,
            "expected per-subtype deleteCopay(@PathVariable id: UUID); saw:\n$src")
        assertTrue("import java.util.UUID" in src,
            "expected import java.util.UUID; saw:\n$src")
        assertTrue("@PathVariable id: Long" !in src,
            "uuid-PK TPH controller must not bind @PathVariable id: Long; saw:\n$src")
    }

    @Test fun `long PK still binds Long everywhere - regression guard`() {
        val src = generate(KotlinSpringControllerGenerator(), "kuuid-long", uuidFkFixture,
            "acme/demo/PostTable.kt".replace("PostTable", "PostController"))
        assertTrue("fun get(@PathVariable id: Long)" in src,
            "expected get(@PathVariable id: Long) for a field.long PK; saw:\n$src")
        assertTrue("import java.util.UUID" !in src,
            "a uuid-free controller must stay byte-identical (no UUID import); saw:\n$src")
    }
}
